def extract_script(package, mapping, output):
    """Restore the exact referenced 2.4 Lua; keep native battle control."""
    import server19_resources as resources
    if SCRIPT_PATH not in mapping:
        raise BuildError('Missing ExBoss level script')
    _, raw = resources.object_bytes(package, mapping[SCRIPT_PATH])
    _, script = resources.text_asset(raw)
    if hashlib.sha256(script).hexdigest() != SCRIPT_SHA256:
        raise BuildError('ExBoss level script fingerprint changed')
    target = output / SCRIPT_PATH
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(script)


def adapt_ability_data(payload, stringmap):
    """Translate the proven fixed-string wrapper and 1.9 union tag only."""
    from .material_training import adapt_ability_data as adapt_roots
    return adapt_roots(payload, stringmap, ABILITY_EDITS)


def adapt_monster_data(payload, stringmap):
    """Project the fingerprinted Sin_EX variant without replacing its AI."""
    from .material_training import adapt_ability_data as adapt_roots
    return adapt_roots(payload, stringmap, MONSTER_EDITS)

_MODELS = {
    'Entities/Monster/Boss/BOSS_012/SinDemonEx/Boss_012': 'Boss_012',
    'Entities/Monster/Boss/BOSS_050/SinDemonEx/Boss_050': 'Boss_050',
    'Entities/Monster/Boss/BOSS_070/SinDemonEx/Boss_070': 'Boss_070',
    'Entities/Monster/Boss/BOSS_080/SinDemonEx/Boss_080': 'Boss_080',
    'Entities/Monster/Boss/BOSS_090/SinDemonEx/Boss_090': 'Boss_090',
    'Entities/Monster/Boss/BOSS_100/SinDemonEx/Boss_100': 'Boss_100',
    'Entities/Monster/Robot/RO_012/SinDemonEx/Boss_RO_012': 'Boss_RO_012',
    'Entities/Avatar/Himeko_C4_BZ/SinDemonEx/Boss_Himeko_C4': 'Boss_Himeko_C4',
    'Entities/Avatar/Fuka_C2_NL/SinDemonEx/Boss_Fuka_C2': 'Boss_Fuka_C2',
}


def adapt(rows, native_resource_paths):
    native = {path.lower() for path in native_resource_paths}
    seen = set()
    for row in rows:
        source = row.get('BossPrefabPath')
        if source not in _MODELS:
            continue
        target = 'Entities/SinDemonEx/' + _MODELS[source]
        if target.lower() not in native:
            raise BuildError('Missing native ExBoss model: ' + target)
        row['BossPrefabPath'] = target
        seen.add(source)
    if seen != _MODELS.keys():
        raise BuildError('Retained ExBoss model sources changed')
    return len(seen)
